import React, { useState, useEffect } from 'react';
import axios from 'axios';

function LoanList({ accountNumber }) {
  const [loans, setLoans] = useState([]);
  const [selectedLoan, setSelectedLoan] = useState(null);
  const [amount, setAmount] = useState('');
  const [password, setPassword] = useState('');

  useEffect(() => {
    axios.get(`http://localhost:3001/getLoanInfo/${accountNumber}`)
      .then(res => setLoans(res.data.loans))
      .catch(err => alert('Failed to fetch loans'));
  }, [accountNumber]);

  const payEMI = () => {
    if (!selectedLoan) return;
    axios.post(`http://localhost:3001/payEMI/${selectedLoan.loan_id}`, {
      account_number: accountNumber,
      amount: selectedLoan.emi,
      password
    })
      .then(res => alert(res.data.message))
      .catch(err => alert(err.response?.data?.message || 'Payment failed'));
  };

  return (
    <div className="p-4">
      <h2 className="text-xl font-bold mb-4">Loan Info</h2>
      {loans.map(loan => (
        <div key={loan.loan_id} className="border rounded p-2 mb-2">
          <p><strong>Loan ID:</strong> {loan.loan_id}</p>
          <p><strong>Amount:</strong> ₹{loan.amount}</p>
          <p><strong>Interest Rate:</strong> {loan.interest_rate}%</p>
          <p><strong>Status:</strong> {loan.status}</p>
          <p><strong>EMI:</strong> ₹{loan.emi}</p>
          <button className="bg-blue-500 text-white px-2 py-1 mt-2 rounded"
            onClick={() => setSelectedLoan(loan)}>Pay EMI</button>
        </div>
      ))}
      {selectedLoan && (
        <div className="mt-4 border p-4 rounded bg-gray-100">
          <h3 className="text-lg font-semibold">Pay EMI for Loan {selectedLoan.loan_id}</h3>
          <p>Amount: ₹{selectedLoan.emi}</p>
          <input
            type="password"
            placeholder="Enter Password"
            value={password}
            onChange={e => setPassword(e.target.value)}
            className="border p-1 my-2 block w-full"
          />
          <button onClick={payEMI} className="bg-green-600 text-white px-4 py-2 rounded">
            Confirm Payment
          </button>
        </div>
      )}
    </div>
  );
}

export default LoanList;
